        data: [["Bond", "Length / pm", "Bond enthalpy / kJ mol⁻¹"], ["C–C", "154", "346"], ["C=C", "134", "614"], ["C≡C", "120", "839"], ["C–N", "147", "305"], ["C=N", "129", "615"]],
